/// Every command name registered by this plugin. The `tauri-plugin` build dep
/// auto-generates `permissions/autogenerated/commands/<cmd>.toml` for each,
/// exposing `allow-<cmd>` and `deny-<cmd>` permission identifiers.
const COMMANDS: &[&str] = &["hash_string", "hash_file"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS)
        .global_api_script_path("./api-iife.js")
        .build();
}
